Item.method_code:
window.require(['EffectivityServices/Scripts/EffectivityCriteriaDialog'], function (
	EffectivityCriteriaDialog
) {
	const effectivityScopeIdParameterName = 'EffectivityScopeId';
	const effectivityCriteriaDefinitionParameterName =
		'EffectivityCriteriaDefinition';
	const effectivityResolutionConfigurationQueryDefinitionIdParameterName =
		'EffectivityResolutionConfigurationQueryDefinitionId';

	const constructTermAsJson = function (id, datatype, value) {
		const termNodeAsJsonObject = {
			eq: {
				variable: {
					'@attrs': {
						id: id
					}
				}
			}
		};

		if (!datatype) {
			termNodeAsJsonObject.eq['named-constant'] = {
				'@attrs': {
					id: value
				}
			};
		} else {
			termNodeAsJsonObject.eq.constant = {
				'@attrs': {
					type: datatype
				},
				'@value': value
			};
		}

		return termNodeAsJsonObject;
	};

	// create EffectivityCriteriaDialog instance once
	// and get effectivity resolution configuration QD ID once when "Set Effectivity Criteria" button is clicked first time
	if (!window.effectivityCriteriaDialog) {
		window.effectivityCriteriaDialog = new EffectivityCriteriaDialog(
			window.aras
		);
		window.effectivityResolutionConfigurationQueryDefinitionId = aras.evalMethod(
			'effs_getResolutionCfgQdIdByTgvId',
			'',
			{
				treeGridViewDefinitionId: options.itemId
			}
		);
	}

	const { tgvContext } = options;
	window.effectivityCriteriaDialog.show().then(function (scope) {
		if (scope === undefined) {
			return;
		}

		if (scope === null) {
			scope = {
				id: '',
				variables: []
			};
		}

		const effectivityCriteriaDefinition = Array.prototype.filter
			.call(scope.variables, function (variable) {
				return !!variable.value;
			})
			.reduce(function (prevConstructedTerms, variable) {
				return (
					prevConstructedTerms +
					ArasModules.jsonToXml(
						constructTermAsJson(variable.id, variable.datatype, variable.value)
					)
				);
			}, '');

		const tgvParametersProvider = tgvContext.parametersProvider;
		tgvParametersProvider.setParameter(
			effectivityResolutionConfigurationQueryDefinitionIdParameterName,
			// set empty string to EffectivityResolutionConfigurationQueryDefinitionId TGV parameter
			// when EffectivityScopeId TGV parameter value is an empty string in order to disable effectivity resolution
			// and avoid "'effs_scope_id' node must have a proper value" exception from the EffectivityServicesGetEffectiveItems internal method
			scope.id === ''
				? ''
				: window.effectivityResolutionConfigurationQueryDefinitionId
		);
		tgvParametersProvider.setParameter(
			effectivityScopeIdParameterName,
			scope.id
		);
		tgvParametersProvider.setParameter(
			effectivityCriteriaDefinitionParameterName,
			effectivityCriteriaDefinition
		);
		tgvContext.reload();
	});
});
